export function s2BoundsFor(predioId: string): GeoBounds | null {
  return S2_PREDIO_BOUNDS[predioId] ?? null
}

export function droneBoundsFor(predioId: string, date: string): GeoBounds | null {
  return DRONE_FLIGHT_BOUNDS[`${predioId}|${date}`] ?? s2BoundsFor(predioId)
}

export function cuartelRings(cuartelIds: string[]): LonLat[][] {
  const out: LonLat[][] = []
  for (const id of cuartelIds) {
    const g = CUARTEL_GEOMS[id]
    if (g) out.push(...g.rings)
  }
  return out
}
